macro.command:
if (args[0]?.macroPass !== "postDamageRoll" || workflow.aborted) return;
if (workflow.actor?.uuid !== macroItem.actor?.uuid) return;
if (workflow._classpackDestructiveWrathChecked) return;

const api = globalThis.dnd5eClasspack;
if (!api?.resources || !api.dialogUtils) return;
const actor = workflow.actor;
const resource = actor.items.find(item =>
  item._stats?.compendiumSource?.endsWith(".WPevnsjK8Cjd9Fcl")
) ?? actor.items.find(item => [
  "引导神力(牧师) Channel Divinity",
  "引导神力（牧师） Channel Divinity",
  "引导神力 Channel Divinity", "Channel Divinity"
].includes(item.name));
if (!resource || api.resources.remaining(resource) < 1) return;

function refresh(roll) {
  for (const term of roll.terms) {
    if (term.roll) refresh(term.roll);
    for (const inner of term.rolls ?? []) refresh(inner);
    if (term.rolls && Array.isArray(term.results)) {
      term.results.forEach((result, i) => {
        if (term.rolls[i]) result.result = term.rolls[i].total;
      });
    }
  }
  roll._total = roll._evaluateTotal();
  return roll;
}

function maximize(original) {
  const revised = original.constructor.fromData(
    foundry.utils.deepClone(original.toJSON())
  );
  const defaults = original.options.type
    ? [original.options.type] : Array.from(original.options.types ?? []);
  let changed = false;
  for (const die of revised.dice) {
    const explicit = String(die.options.flavor ?? "").toLowerCase()
      .split(/[^a-z]+/).filter(type => Object.hasOwn(CONFIG.DND5E.damageTypes, type));
    const types = explicit.length ? explicit : defaults.length === 1 ? defaults : [];
    if (!types.some(type => ["lightning", "thunder"].includes(type))) continue;
    for (const result of die.results) {
      if (result.active === false || result.discarded) continue;
      if (result.result === die.faces && result.count === undefined) continue;
      result.result = die.faces;
      delete result.count;
      changed = true;
    }
  }
  return { roll: changed ? refresh(revised) : original, changed };
}

const groups = [
  ["damageRolls", "setDamageRolls"],
  ["bonusDamageRolls", "setBonusDamageRolls"],
  ["otherDamageRolls", "setOtherDamageRolls"]
].map(([key, setter]) => {
  const before = [...(workflow[key] ?? [])];
  const results = before.map(maximize);
  return { before, setter, after: results.map(r => r.roll),
    changed: results.some(r => r.changed) };
}).filter(group => group.changed);
if (!groups.length) return;

workflow._classpackDestructiveWrathChecked = true;
const confirmed = await api.dialogUtils.confirm(
  macroItem.name,
  "是否消耗 1 次引导神力，将本次伤害中的闪电和雷鸣伤害骰取最大值？",
  { userId: api.firstOwner(actor, true) }
);
if (!confirmed) return;

let receipt;
try {
  receipt = await api.resources.consume([{ itemUuid: resource.uuid, amount: 1 }], {
    id: `${workflow.uuid ?? workflow.id ?? foundry.utils.randomID()}:${macroItem.uuid}:destructive-wrath`
  });
  for (const group of groups) await workflow[group.setter](group.after);
} catch (error) {
  // 结算失败时恢复本次原伤害，再退回仍可确认属于本次的资源扣除。
  for (const group of groups) {
    try { await workflow[group.setter](group.before); }
    catch (restoreError) { console.error("毁灭狂怒：恢复伤害失败", restoreError); }
  }
  for (const entry of [...(receipt?.entries ?? [])].reverse()) {
    const item = await fromUuid(entry.itemUuid);
    if (Number(item?.system.uses.spent) === entry.after) {
      await item.update({ "system.uses.spent": entry.before });
    }
  }
  console.error("毁灭狂怒", error);
  ui.notifications.error("毁灭狂怒未能完成，请检查控制台、伤害结果和引导神力剩余次数。");
}
